     4→import { useMutation } from "@tanstack/react-query";
     5→import { useRouter } from "next/navigation";
     6→import { Button } from "@/components/ui/button";
     7→import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
     8→import { useToast } from "@/hooks/use-toast";
     9→import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
    10→import { AlertTriangle, CheckCircle, Loader2, AlertCircle } from "lucide-react";
    11→import { importGedcom } from "@/actions/gedcom";
    12→import type {
    13→  ValidateGedcomResult,
    14→  ImportGedcomResult,
    15→} from "@/actions/gedcom";
    16→
    17→interface GedcomImportPreviewProps {
    18→  result: ValidateGedcomResult;
    19→  file: File;
    20→  onReset: () => void;
    21→}
    22→
    23→async function performImport(file: File): Promise<ImportGedcomResult> {
    24→  const formData = new FormData();
    25→  formData.append("file", file);
    26→  return importGedcom(formData);
    27→}
    28→
    29→export function GedcomImportPreview({
    30→  result,
    31→  file,
    32→  onReset,
    33→}: GedcomImportPreviewProps) {
    34→  const { toast } = useToast();
    35→  const router = useRouter();
    36→  const [isImporting, setIsImporting] = useState(false);
    37→
    38→  const mutation = useMutation({
    39→    mutationFn: performImport,
    40→    onSuccess: (data) => {
    41→      if (data.success) {
    42→        toast({
    43→          title: "Import Successful",
    44→          description: data.message,
    45→        });
    46→        router.refresh();
    47→        // Auto-close after a short delay
    48→        setTimeout(() => {
    49→          onReset();
    50→        }, 2000);
    51→      } else {
    52→        toast({
    53→          title: "Import Failed",
    54→          description: data.message,
    55→          variant: "destructive",
    56→        });
    57→      }
    58→    },
    59→    onError: (error: Error) => {
    60→      toast({
    61→        title: "Import Error",
    62→        description: error.message,
    63→        variant: "destructive",
    64→      });
    65→    },
    66→    onSettled: () => {
    67→      setIsImporting(false);
    68→    },
    69→  });
    70→
    71→  const handleImport = () => {
    72→    setIsImporting(true);
    73→    mutation.mutate(file);
    74→  };
    75→
    76→  const hasErrors = result.preview?.errors && result.preview.errors.length > 0;
    77→  const errorCount =
    78→    result.preview?.errors?.filter(
    79→      (e) => e.type === "validation_error" || e.type === "mapping_error"
    80→    ).length || 0;
