     2→ * GEDCOM Data Mapper
     3→ * Bidirectional mapping between GEDCOM and Vamsa data models
     4→ */
     5→
     6→import type { GedcomFile } from "./types";
     7→import {
     8→  type MappingResult,
     9→  type MappingError,
    10→  type VamsaPerson,
    11→  type VamsaRelationship,
    12→  type GedcomIndividualData,
    13→  type GedcomFamilyData,
    14→  type MapOptions,
    15→  type ParsedName,
    16→} from "./mapper-types";
    17→import { GedcomParser } from "./parser";
    18→
    19→/**
    20→ * Generate a CUID-like ID for use in mapping operations
    21→ * Uses timestamp + random characters for collision-resistant IDs
    22→ */
    23→function generateId(): string {
    24→  const timestamp = Date.now().toString(36);
    25→  const randomPart = Math.random().toString(36).substring(2, 9);
    26→  return `c${timestamp}${randomPart}`;
    27→}
    28→
    29→export class GedcomMapper {
    30→  private parser: GedcomParser;
    31→
    32→  constructor() {
    33→    this.parser = new GedcomParser();
    34→  }
    35→
    36→  /**
    37→   * Convert parsed GEDCOM data to Vamsa data model
    38→   */
    39→  mapFromGedcom(gedcomFile: GedcomFile, options?: MapOptions): MappingResult {
    40→    const people: VamsaPerson[] = [];
    41→    const relationships: VamsaRelationship[] = [];
    42→    const errors: MappingError[] = [];
    43→    const warnings: string[] = [];
    44→
    45→    // 1. Validate GEDCOM structure
    46→    if (!options?.skipValidation) {
    47→      const validationErrors = this.parser.validate(gedcomFile);
    48→      for (const error of validationErrors) {
    49→        if (error.severity === "error") {
    50→          errors.push({
    51→            type: "invalid_format",
    52→            source: "INDI",
    53→            id: "unknown",
    54→            field: "structure",
    55→            message: error.message,
    56→          });
    57→        } else {
    58→          warnings.push(error.message);
    59→        }
    60→      }
    61→    }
    62→
    63→    // 2. Create ID mapping (GEDCOM xrefs -> Vamsa CUIDs)
    64→    const idMap = new Map<string, string>();
    65→    for (const individual of gedcomFile.individuals) {
    66→      if (individual.id) {
    67→        idMap.set(individual.id, generateId());
    68→      }
    69→    }
    70→
    71→    // 3. Map individuals (INDI -> Person)
    72→    for (const record of gedcomFile.individuals) {
    73→      if (!record.id) continue;
    74→
    75→      const parsed = this.parser.parseIndividual(record);
    76→      const vamsaId = idMap.get(parsed.id);
    77→
    78→      if (!vamsaId) {
    79→        errors.push({
    80→          type: "missing_data",
    81→          source: "INDI",
    82→          id: parsed.id,
    83→          field: "id",
    84→          message: `Failed to generate ID for individual ${parsed.id}`,
    85→        });
    86→        continue;
    87→      }
    88→
    89→      // Parse name
    90→      const primaryName = parsed.names[0];
    91→      const parsedName = primaryName
    92→        ? this.parseName(primaryName.full)
    93→        : { firstName: "Unknown", lastName: "Unknown" };
    94→
    95→      if (!parsedName.firstName) {
    96→        parsedName.firstName = "Unknown";
    97→      }
    98→      if (!parsedName.lastName) {
    99→        parsedName.lastName = "Unknown";
   100→      }
   101→
   102→      // Determine if person is living
   103→      const isLiving = !parsed.deathDate;
   104→
   105→      // Convert date strings to Date objects
   106→      const dateOfBirth = parsed.birthDate
   107→        ? this.parseISODate(parsed.birthDate)
   108→        : undefined;
   109→      const dateOfPassing = parsed.deathDate
   110→        ? this.parseISODate(parsed.deathDate)
   111→        : undefined;
   112→
   113→      // Map gender
   114→      const gender = this.unmapGender(parsed.sex);
   115→
   116→      const person: VamsaPerson = {
   117→        id: vamsaId,
   118→        firstName: parsedName.firstName,
   119→        lastName: parsedName.lastName,
   120→        dateOfBirth,
   121→        dateOfPassing,
   122→        birthPlace: parsed.birthPlace,
   123→        gender,
   124→        profession: parsed.occupation,
   125→        bio: parsed.notes.join("\n") || undefined,
   126→        isLiving,
   127→      };
   128→
   129→      people.push(person);
   130→    }
   131→
   132→    // 4. Map families (FAM -> Relationships)
   133→    for (const record of gedcomFile.families) {
   134→      if (!record.id) continue;
   135→
   136→      const parsed = this.parser.parseFamily(record);
   137→
   138→      // Create spouse relationships
   139→      if (parsed.husband && parsed.wife) {
   140→        const husbandId = idMap.get(parsed.husband);
   141→        const wifeId = idMap.get(parsed.wife);
   142→
   143→        if (!husbandId || !wifeId) {
   144→          if (!options?.ignoreMissingReferences) {
   145→            errors.push({
   146→              type: "broken_reference",
   147→              source: "FAM",
   148→              id: parsed.id,
   149→              field: "HUSB/WIFE",
   150→              message: `Broken spouse reference in family ${parsed.id}`,
   151→            });
   152→          }
   153→          continue;
   154→        }
   155→
   156→        const marriageDate = parsed.marriageDate
   157→          ? this.parseISODate(parsed.marriageDate)
   158→          : undefined;
   159→        const divorceDate = parsed.divorceDate
   160→          ? this.parseISODate(parsed.divorceDate)
   161→          : undefined;
   162→
   163→        // Create bidirectional SPOUSE relationships
   164→        relationships.push({
   165→          id: generateId(),
   166→          personId: husbandId,
   167→          relatedPersonId: wifeId,
   168→          type: "SPOUSE",
   169→          marriageDate,
   170→          divorceDate,
   171→          isActive: !divorceDate,
   172→        });
